class GSLWrapper:
    def __init__(self, func):
        self.func = func
        self.params = None
        self.wrapper_func = GSLFunction(self.wrapper)

    def set_params(self, params):
        self.params = params

    def wrapper(self, x):
        return self.func(x, self.params)

def integrate_with_singularity(func, a, b, c):
    wrapper = GSLWrapper(func)
    result = c_double()
    abserr = c_double()
    gsl.gsl_integration_qc25c(byref(result), byref(abserr), a, b, c, 1e-7, 1e-7, wrapper.wrapper_func, None)
    return (result.value, abserr.value, int(gsl.GSL_SUCCESS))

