        self.matrix = gsl_matrix_alloc(rows, cols)

    def __del__(self):
        gsl_matrix_free(self.matrix)

    def set_value(self, row, col, value):
        ctypes.c_double(value).value = gsl_matrix_get(self.matrix, row, col)

    def get_value(self, row, col):
        return gsl_matrix_get(self.matrix, row, col)

def numpy_to_gsl_matrix(np_array):
    rows, cols = np_array.shape
    gsl_mat = GSLMatrix(rows, cols)
    for i in range(rows):
        for j in range(cols):
            gsl_mat.set_value(i, j, np_array[i][j])
    return gsl_mat.matrix

