import ctypes

gslcblas = ctypes.CDLL("/usr/local/gsl/lib/libgslcblas.so", mode=ctypes.RTLD_GLOBAL)
gsl = ctypes.CDLL("/usr/local/gsl/lib/libgsl.so")

class GSLMatrix:
    def __init__(self, matrix):
        self.matrix = matrix
        self.rows = len(matrix)
        self.cols = len(matrix[0])
        self.data_type = ctypes.c_double * (self.rows * self.cols)
        self.ctypes_data = self.data_type(*sum(self.matrix, []))

    def to_c_matrix(self):
        c_matrix = gsl.gsl_matrix_alloc(self.rows, self.cols)
        for i in range(self.rows):
            for j in range(self.cols):
                ctypes.c_double.from_address(ctypes.addressof(c_matrix.data) + i * c_matrix.tda * ctypes.sizeof(ctypes.c_double) + j * ctypes.sizeof(ctypes.c_double)).value = self.ctypes_data[i * self.cols + j]
        return c_matrix

    def free_c_matrix(self, c_matrix):
        gsl.gsl_matrix_free(c_matrix)

def find_minmax_indices(matrix):
    gsl_matrix = GSLMatrix(matrix)
    c_matrix = gsl_matrix.to_c_matrix()
    min_index = ctypes.c_size_t(0)
    max_index = ctypes.c_size_t(0)
    gsl.gsl_matrix_minmax_index(c_matrix, ctypes.byref(min_index), ctypes.byref(max_index))
    gsl_matrix.free_c_matrix(c_matrix)
    return (min_index.value // gsl_matrix.cols, min_index.value % gsl_matrix.cols, max_index.value // gsl_matrix.cols, max_index.value % gsl_matrix.cols)

