def create_gsl_vector(array):
    return gsl.gsl_vector_alloc(len(array)), array

def create_gsl_matrix(matrix):
    nrows, ncols = matrix.shape
    c_matrix = gsl.gsl_matrix_calloc(nrows, ncols)
    for i in range(nrows):
        for j in range(ncols):
            gsl.gsl_matrix_set(c_matrix, i, j, matrix[i, j])
    return c_matrix

def extract_numpy_array_from_gsl_vector(vector):
    data = (ctypes.c_double * vector.size).from_address(ctypes.addressof(vector.data.contents))
    return np.array(data[:vector.size], dtype=np.double)

def extract_numpy_array_from_gsl_matrix(matrix):
    nrows, ncols = matrix.size1, matrix.size2
    data = (ctypes.c_double * (nrows * ncols)).from_address(ctypes.addressof(matrix.data.contents))
    return np.array(data[:nrows * ncols]).reshape(nrows, ncols)

def qrstep(d, f, U, V):
    d_ptr, _ = create_gsl_vector(d)
    f_ptr, _ = create_gsl_vector(f)
    U_ptr, U_data = create_gsl_matrix(U)
    V_ptr, V_data = create_gsl_matrix(V)

