        gsl.gsl_integration_qag(func, self.a, self.b, self.epsabs, self.epsrel,
                                  self.limit, self.key, self.workspace,
                                  ctypes.byref(self.result),
                                  ctypes.byref(self.abserr))
        return (self.result.value, self.abserr.value)

    def __del__(self):
        gsl.gsl_integration_workspace_free(self.workspace)

