import numpy as np
import ctypes
from scipy import weave

class GSLMatrix:
    def __init__(self, array):
        self.array = np.ascontiguousarray(array, dtype=np.float64)
        self.rows = self.array.shape[0]
        self.cols = self.array.shape[1]
        self.data = self.array.ctypes.data_as(ctypes.POINTER(ctypes.c_double))

    def to_gsl_matrix(self):
        return gsl.gsl_matrix_alloc(self.rows, self.cols)

    def update_from_gsl_matrix(self, gsl_mat):
        ctypes.memmove(self.data, gsl_mat.data_d, self.rows * self.cols * ctypes.sizeof(ctypes.c_double))

class GSLVector:
    def __init__(self, array):
        self.array = np.ascontiguousarray(array, dtype=np.float64)
        self.size = self.array.shape[0]
        self.data = self.array.ctypes.data_as(ctypes.POINTER(ctypes.c_double))

    def to_gsl_vector(self):
        return gsl.gsl_vector_alloc(self.size)

    def update_from_gsl_vector(self, gsl_vec):
        ctypes.memmove(self.data, gsl_vec.data_d, self.size * ctypes.sizeof(ctypes.c_double))

def numpy_to_gsl_matrix(matrix):
    return GSLMatrix(matrix).to_gsl_matrix()

def numpy_to_gsl_vector(vector):
    return GSLVector(vector).to_gsl_vector()

def qr_ud_decomp(U, D, Y, T):
    gsl.U = numpy_to_gsl_matrix(U)
    gsl.D = numpy_to_gsl_matrix(D)
    gsl.Y = numpy_to_gsl_matrix(Y)
    gsl.T = numpy_to_gsl_matrix(T)

    gsl.gsl_linalg_QR_UD_decomp(gsl.U, gsl.D, gsl.Y, gsl.T)

    U.update_from_gsl_matrix(gsl.U)
    D.update_from_gsl_matrix(gsl.D)
    Y.update_from_gsl_matrix(gsl.Y)
    T.update_from_gsl_matrix(gsl.T)

    return Y.array, T.array

