        raise ValueError("U must have the same dimensions as A")

    if V is not None and V.shape != (B.shape[0], B.shape[1]):
        raise ValueError("V must have the same dimensions as B")

    if work is not None and len(work) != max(A.shape[0], B.shape[0]) - 2:
