class GSLSpMatrix:
    def __init__(self, size):
        self.matrix = gsl.gsl_spmatrix_alloc(size, size)

    def set_sparse_matrix_element(self, row, col, value):
        gsl.gsl_spmatrix_set(self.matrix, row, col, value)

    def get_sparse_matrix_elements(self):
        elements = []
        for i in range(gsl.gsl_spmatrix_size1(self.matrix)):
            for j in range(gsl.gsl_spmatrix_size2(self.matrix)):
                element = gsl.gsl_spmatrix_get(self.matrix, i, j)
                if element != 0.0:
                    elements.append((i, j, element))
        return elements

    def swap_sparse_matrix_elements(self, i, j):
        for k in range(gsl.gsl_spmatrix_size1(self.matrix)):
            for l in range(gsl.gsl_spmatrix_size2(self.matrix)):
                if gsl.gsl_spmatrix_get(self.matrix, k, l) != 0.0:
                    value = gsl.gsl_spmatrix_get(self.matrix, k, l)
                    if (k, l) == (i, j):
                        gsl.gsl_spmatrix_set(self.matrix, i, j, gsl.gsl_spmatrix_get(self.matrix, k, l))
                    elif (k, l) == (j, i):
                        gsl.gsl_spmatrix_set(self.matrix, j, i, value)

