class GSLMatrix:
    def __init__(self, data):
        self.data = data
        self.rows = len(data)
        self.cols = len(data[0])
        self.handle = gsl.gsl_matrix_alloc(self.rows, self.cols)
        for i in range(self.rows):
            for j in range(self.cols):
                gsl.gsl_matrix_set(self.handle, i, j, data[i][j].real + data[i][j].imag * 1j)

    def __del__(self):
        gsl.gsl_matrix_free(self.handle)

def list_to_gsl_matrix(matrix):
    return GSLMatrix(matrix)

def add_matrices(matrix_a, matrix_b):
    if matrix_a.rows != matrix_b.rows or matrix_a.cols != matrix_b.cols:
        raise ValueError("Matrices must have the same dimensions")
    result = gsl.gsl_matrix_add(matrix_a.handle, matrix_b.handle)
    return list_to_gsl_matrix([[gsl.gsl_matrix_get(result, i, j) for j in range(matrix_a.cols)] for i in range(matrix_a.rows)])

