class gsl_combination(ctypes.Structure):
    _fields_ = ["data", "size", "t"]

next_combination = gsl.gsl_combination_next
next_combination.argtypes = [ctypes.POINTER(gsl_combination), ctypes.c_size_t]
next_combination.restype = ctypes.c_int

def get_next_combination(current_combination, n):
    size = len(current_combination)
    comb = gsl_combination((ctypes.c_size_t * (size + 1))(*([0] + list(current_combination))), size, n)
    if next_combination(ctypes.byref(comb), n) == 0:
        return tuple(comb.data[1:])
    else:
        return None

