        self.rows = len(data)
        self.cols = len(data[0])
        self.data = (ctypes.c_double * (self.rows * self.cols))(*sum(data, []))
        self.matrix = gsl.gsl_matrix_calloc(self.rows, self.cols)
        if not self.matrix:
            raise MemoryError("Failed to allocate GSL matrix")
        gsl.gsl_matrix_set_data(self.matrix, self.data)

    def __del__(self):
        gsl.gsl_matrix_free(self.matrix)

