    def create_gsl_matrix(data):
        return GSLMatrix(data)

    @staticmethod
    def retrieve_gsl_matrix(matrix):
        rows = int(gsl.gsl_matrix_get_rows(matrix))
        cols = int(gsl.gsl_matrix_get_cols(matrix))
        data = (ctypes.c_double * (rows * cols)).in_dll(gsl, "gsl_matrix_data")
        return [[data[i*cols + j] for j in range(cols)] for i in range(rows)]

    @staticmethod
    def free_gsl_matrix(matrix):
        gsl.gsl_matrix_free(matrix)

