class GSLMatrix(ctypes.Structure):
    _fields_ = ["size1", "size2", "tda", "data"]

def transpose_matrix(matrix):
    rows = len(matrix)
    cols = len(matrix[0])
    data = (ctypes.c_double * (rows * cols))()
    for i in range(rows):
        for j in range(cols):
            data[i * cols + j] = matrix[i][j]

    gsl_matrix = GSLMatrix(rows, cols, cols, data)
    gsl.gsl_matrix_transpose(ctypes.byref(gsl_matrix))

    transposed_matrix = [[0.0] * rows for _ in range(cols)]
    for i in range(rows):
        for j in range(cols):
            transposed_matrix[j][i] = data[i * cols + j]

    return transposed_matrix

