class GSL_Histogram2D:
    def __init__(self, data):
        self.data = data
        self.hist = None

    def create_histogram(self, ranges_x, ranges_y):
        x_size = len(ranges_x) - 1
        y_size = len(ranges_y) - 1
        self.hist = gsl.gsl_histogram2d_alloc(x_size, y_size)
        for i in range(x_size + 1):
            gsl.gsl_histogram2d_set_ranges(self.hist, ctypes.c_double(ranges_x[i]), ctypes.c_double(ranges_x[i+1]))
        for j in range(y_size + 1):
            gsl.gsl_histogram2d_set_ranges(self.hist, ctypes.c_double(ranges_y[j]), ctypes.c_double(ranges_y[j+1]))

    def fill_histogram(self):
        for x, y in self.data:
            index_x = gsl.gsl_histogram2d_find(self.hist, ctypes.c_double(x), ctypes.c_double(y))
            if index_x != -1:
                gsl.gsl_histogram2d_increment(self.hist, index_x)

