class GSLMatrix:
    def __init__(self, matrix):
        self.matrix = matrix
        self.rows = len(matrix)
        self.cols = len(matrix[0])
        self.data_type = gsl.gsl_matrix_float

    def is_positive_definite(self):
        matrix_ptr = self.data_type(self.rows, self.cols)
        for i in range(self.rows):
            for j in range(self.cols):
                ctypes.memmove(ctypes.addressof(matrix_ptr.data[0]) + (i * self.cols + j) * 4, ctypes.byref(ctypes.c_float(self.matrix[i][j])), 4)
        result = gsl.gsl_linalg_cholesky_decomp(matrix_ptr)
        if result != 0:
            return False
        else:
            return True

    def cholesky_decomp(self):
        if not self.is_positive_definite():
            raise ValueError("Matrix is not positive definite")
        matrix_ptr = self.data_type(self.rows, self.cols)
        for i in range(self.rows):
            for j in range(self.cols):
                ctypes.memmove(ctypes.addressof(matrix_ptr.data[0]) + (i * self.cols + j) * 4, ctypes.byref(ctypes.c_float(self.matrix[i][j])), 4)
        gsl.gsl_linalg_cholesky_decomp(matrix_ptr)
        lower_triangular = [[matrix_ptr.data[j * self.cols + i].value for i in range(j+1)] for j in range(self.rows)]
        return lower_triangular

