class GslRstatQuantileWorkspace:
    def __init__(self, size):
        self._workspace = gsl.gsl_rstat_quantile_alloc(size)
        if not self._workspace:
            raise MemoryError("Failed to allocate quantile workspace")

    def reset(self):
        gsl.gsl_rstat_quantile_reset(self._workspace)

    def add(self, value):
        gsl.gsl_rstat_quantile_add(self._workspace, ctypes.c_double(value))

    def get_quantile(self, p):
        return gsl.gsl_rstat_quantile_get(self._workspace, ctypes.c_double(p))

    def free(self):
        gsl.gsl_rstat_quantile_free(self._workspace)

def compute_quantile(p, values):
    workspace = GslRstatQuantileWorkspace(len(values))
    try:
        for value in values:
            workspace.add(value)
        return workspace.get_quantile(p)
    finally:
        workspace.free()

