def gsl_cdf_negative_binomial_P(k, p, n):
    k_c = ctypes.c_uint(k)
    p_c = ctypes.c_double(p)
    n_c = ctypes.c_double(n)
    result = gsl.gsl_cdf_negative_binomial_P(k_c, p_c, n_c)
    return float(result.value)

def gsl_cdf_negative_binomial_Q(k, p, n):
    k_c = ctypes.c_uint(k)
    p_c = ctypes.c_double(p)
    n_c = ctypes.c_double(n)
    result = gsl.gsl_cdf_negative_binomial_Q(k_c, p_c, n_c)
    return float(result.value)

def test_gsl_cdf_negative_binomial_P():
    assert abs(gsl_cdf_negative_binomial_P(0, 0.5, 1) - 0.5) < 1e-6
    assert abs(gsl_cdf_negative_binomial_P(1, 0.5, 2) - 0.75) < 1e-6
    try:
        gsl_cdf_negative_binomial_P(-1, 0.5, 1)
        assert False
    except ValueError:
        pass

def test_gsl_cdf_negative_binomial_Q():
    assert abs(gsl_cdf_negative_binomial_Q(0, 0.5, 1) - 0.5) < 1e-6
    assert abs(gsl_cdf_negative_binomial_Q(1, 0.5, 2) - 0.25) < 1e-6
    try:
        gsl_cdf_negative_binomial_Q(-1, 0.5, 1)
        assert False
    except ValueError:
        pass

